import re
from typing import List, Tuple

# Token types
NUMBER, PLUS, MINUS, TIMES, DIVIDE, LPAREN, RPAREN, EOF = (
    'NUMBER', 'PLUS', 'MINUS', 'TIMES', 'DIVIDE', 'LPAREN', 'RPAREN', 'EOF'
)

# Token representation
class Token:
    def __init__(self, type_: str, value=None):
        self.type = type_
        self.value = value
    def __repr__(self):
        return f'Token({self.type}, {self.value})'

# Lexer: converts the input string into a list of tokens
def tokenize(expr: str) -> List[Token]:
    token_spec = [
        (NUMBER,  r'\d+(\.\d*)?|\.\d+'),  # integers or decimals
        (PLUS,    r'\+'),
        (MINUS,   r'-'),
        (TIMES,   r'\*'),
        (DIVIDE,  r'/'),
        (LPAREN,  r'\('),
        (RPAREN,  r'\)'),
        ('SKIP',  r'\s+'),                # skip spaces
    ]
    tok_regex = '|'.join(f'(?P<{name}>{pattern})' for name, pattern in token_spec)
    tokens = []
    for mo in re.finditer(tok_regex, expr):
        kind = mo.lastgroup
        if kind == 'SKIP':
            continue
        value = mo.group()
        if kind == NUMBER:
            value = float(value)
        tokens.append(Token(kind, value))
    tokens.append(Token(EOF))
    return tokens

# Parser / Evaluator using recursive descent
class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0
        self.current = self.tokens[self.pos]

    def consume(self, token_type: str):
        if self.current.type == token_type:
            self.pos += 1
            self.current = self.tokens[self.pos]
        else:
            raise ValueError(f'Expected {token_type} but got {self.current.type}')

    # Grammar:
    # expr   : term ((PLUS|MINUS) term)*
    # term   : factor ((TIMES|DIVIDE) factor)*
    # factor : (PLUS|MINUS) factor | NUMBER | LPAREN expr RPAREN

    def parse(self) -> float:
        return self.expr()

    def expr(self) -> float:
        result = self.term()
        while self.current.type in (PLUS, MINUS):
            op = self.current.type
            self.consume(op)
            right = self.term()
            if op == PLUS:
                result += right
            else:
                result -= right
        return result

    def term(self) -> float:
        result = self.factor()
        while self.current.type in (TIMES, DIVIDE):
            op = self.current.type
            self.consume(op)
            right = self.factor()
            if op == TIMES:
                result *= right
            else:
                result /= right
        return result

    def factor(self) -> float:
        token = self.current
        if token.type == PLUS:
            self.consume(PLUS)
            return self.factor()
        if token.type == MINUS:
            self.consume(MINUS)
            return -self.factor()
        if token.type == NUMBER:
            self.consume(NUMBER)
            return token.value
        if token.type == LPAREN:
            self.consume(LPAREN)
            val = self.expr()
            self.consume(RPAREN)
            return val
        raise ValueError(f'Unexpected token: {token}')

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression containing non‑negative numbers,
    + - * /, parentheses, spaces and unary minus, with normal precedence.
    """
    tokens = tokenize(expr)
    parser = Parser(tokens)
    return parser.parse()
